import {ResponseError} from '@github-ui/react-core/future/response-error'
import type {UseMutationOptions} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import * as z from 'zod'

import {getMaybeJSONErrorMessage} from '../helpers/extract-errors'

const checkboxBooleanPreprocessor = (value: unknown) => (typeof value === 'boolean' ? value : String(value) === '1')
const strToNumPreprocessor = (value: unknown) => (typeof value === 'string' && value.length < 1 ? 0 : Number(value))

export const updateCustomModelSchema = z.lazy(() =>
  z.object({
    id: z.preprocess(strToNumPreprocessor, z.number().int().positive()),
    name: z.string().optional(),
    enabled: z.preprocess(checkboxBooleanPreprocessor, z.boolean()),
    maxOutputTokens: z.preprocess(strToNumPreprocessor, z.number().int().nonnegative()).optional(),
    maxInputTokens: z.preprocess(strToNumPreprocessor, z.number().int().nonnegative()).optional(),
    toolCalling: z.preprocess(checkboxBooleanPreprocessor, z.boolean()).optional(),
    vision: z.preprocess(checkboxBooleanPreprocessor, z.boolean()).optional(),
    thinking: z.preprocess(checkboxBooleanPreprocessor, z.boolean()).optional(),
  }),
)

export type UpdateCustomModelItem = z.infer<typeof updateCustomModelSchema>

export function updateCustomModelMutationOptions(
  org: string,
): UseMutationOptions<void, ResponseError, UpdateCustomModelItem> {
  return {
    async mutationFn(update) {
      const res = await reactFetchJSON(`/organizations/${org}/settings/copilot/custom-models/${update.id}`, {
        method: 'PUT',
        body: {
          copilot_chat_enabled: update.enabled,
          name: update.name,
          capability_attributes: {
            max_output_tokens: update.maxOutputTokens,
            max_input_tokens: update.maxInputTokens,
            thinking: update.thinking ?? false,
            tool_calling: update.toolCalling ?? false,
            vision: update.vision ?? false,
          },
        },
      })
      if (!res.ok) {
        const message = await getMaybeJSONErrorMessage(res)
        throw new ResponseError(message ?? 'Failed to update custom model, please try again.', res)
      }
    },
  }
}
