import {Button, Stack} from '@primer/react'
import {type FormEvent, forwardRef, useCallback, useImperativeHandle, useRef} from 'react'

import type {ValidationKind} from '../helpers/validation'
import type {CustomModel} from '../types'
import {FormValidationNode} from './FormValidationNode'
import {ModelConfigurationFields} from './ModelConfigurationFields'

interface ModelConfigurationSubFormProps {
  model: CustomModel
  customKeyName?: string
  validation?: Record<string, ValidationKind>
  disabled?: boolean
  formId?: string
  showButtons?: boolean
  onSave?: (modelId: number, formData: FormData) => void
  onCancel?: () => void
}

export const ModelConfigurationSubForm = forwardRef<HTMLFormElement, ModelConfigurationSubFormProps>(
  function ModelConfigurationSubForm(
    {customKeyName, disabled, formId, model, onCancel, onSave, showButtons = false, validation},
    ref,
  ) {
    const formRef = useRef<HTMLFormElement>(null)

    // Expose the form ref to parent components
    useImperativeHandle(ref, () => formRef.current as HTMLFormElement, [])

    const handleSave = useCallback(() => {
      if (formRef.current && onSave) {
        const formData = new FormData(formRef.current)
        onSave(model.id, formData)
      }
    }, [model, onSave])

    const handleFormSubmit = useCallback(
      (event: FormEvent<HTMLFormElement>) => {
        event.preventDefault()
        handleSave()
      },
      [handleSave],
    )

    return (
      <Stack className="height-full">
        {customKeyName && (
          <div className="pb-3">
            <h3 className="f3">
              <span>
                <span>Configure </span>
                <span>{model.name || model.slug}</span>
              </span>
            </h3>
            <p className="fgColor-muted text-small">
              <span>API key: </span>
              <strong>{customKeyName}</strong>
            </p>
          </div>
        )}

        <form ref={formRef} id={formId} onSubmit={handleFormSubmit} className="flex-1">
          <ModelConfigurationFields className="pt-3 px-3" model={model} disabled={disabled} validation={validation} />
        </form>

        {validation?.__general && (
          <div className="mt-2">
            <FormValidationNode item={validation.__general} id="config-general-error" />
          </div>
        )}

        {showButtons && onSave && onCancel && (
          <Stack
            direction="horizontal"
            gap="normal"
            justify="end"
            className="mt-3 pt-3"
            style={{borderTop: '1px solid var(--borderColor-default)'}}
          >
            <Button type="button" onClick={onCancel} disabled={disabled}>
              Cancel
            </Button>
            <Button type="button" variant="primary" onClick={handleSave} disabled={disabled}>
              Save configuration
            </Button>
          </Stack>
        )}
      </Stack>
    )
  },
)

try{ ModelConfigurationSubForm.displayName ||= 'ModelConfigurationSubForm' } catch {}
