import {
  canFetchNewModelsFromProvider,
  getSampleCustomKeyNameFor,
  type Provider,
} from '@github-ui/copilot-byok/providers'
import {ProviderPicker} from '@github-ui/copilot-byok/providers/ProviderPicker'
import {useProviders} from '@github-ui/copilot-byok/providers/react'
import {encrypt} from '@github-ui/encryption'
import {encode} from '@github-ui/encryption/utils'
import {useMutation} from '@github-ui/react-query'
import {SyncIcon, TrashIcon} from '@primer/octicons-react'
import {Banner, Dialog, FormControl, Stack, TextInput, useConfirm} from '@primer/react'
import {type ComponentType, type FormEvent, type RefObject, useCallback, useId, useMemo, useRef, useState} from 'react'
import * as z from 'zod'

import {useCurrentOrg} from '../contexts/CurrentOrgContext'
import {
  applyModelConfigurations,
  buildConfigModel,
  findPersistedModel,
  keyForModel,
} from '../helpers/model-configuration-helpers'
import {getGeneralValidationKind, type ValidationKind, validationKindFromZodError} from '../helpers/validation'
import {useAPIKey} from '../hooks/use-api-key'
import {destroyCustomKeyMutationOptions} from '../queries/destroy-custom-key'
import {updateCustomKeyMutationOptions, type UpdateCustomKeyUpdatePayload} from '../queries/update-custom-key'
import type {CustomKey, CustomModel, SelectorCustomModel} from '../types'
import styles from './AddEditDialog.module.css'
import {FormValidationNode} from './FormValidationNode'
import {ModelConfigurationSubForm} from './ModelConfigurationSubForm'
import {providerFields, providerSchema} from './providers'
import type {ProviderAdditionalData, ProviderFieldProps} from './providers/types'

const randomKey = '*'.repeat(60)

const formSchema = z.lazy(() => {
  const base = z.object({
    provider: z.string().nonempty('A provider must be selected'),
    name: z.string().nonempty('A name is required'),
    api_key: z.string().nullish(),
  })

  return z.union(providerSchema.map(schema => base.extend(schema)))
})

export function EditKeyDialog({
  customKey,
  publicKey,
  // eslint-disable-next-line @eslint-react/no-unstable-default-props
  customModels = [],
  onClose,
  onDelete,
  onUpdate,
  anchorRef,
}: {
  customKey: CustomKey
  publicKey: string
  customModels?: CustomModel[]
  anchorRef?: RefObject<HTMLElement | null>
  onClose: () => void
  onUpdate?: () => void
  onDelete?: () => void
}) {
  const provider = customKey.provider

  const id = useId()
  const nameValidationId = `name-validation-${id}`
  const nameCaptionId = `name-caption-${id}`
  const org = useCurrentOrg()

  // we are not able to display the actual API Key here for security reasons, so we use a random placeholder
  const [formData, setFormData] = useState({
    name: customKey.name,
    api_key: randomKey,
    provider: customKey.provider,
  })

  const [validation, setValidation] = useState<Record<string, ValidationKind>>()
  const [apiKey, setApiKey] = useAPIKey(publicKey)
  const additionalData = useRef<ProviderAdditionalData>(undefined)
  const configFormRef = useRef<HTMLFormElement>(null)

  // State for managing model configuration sub-form
  const [configuringModel, setConfiguringModel] = useState<(SelectorCustomModel & {customKeyId: number}) | null>(null)
  // Use slug as key for non-persisted models, id for persisted models
  const [_modelConfigurations, setModelConfigurations] = useState<Record<string, Record<string, unknown>>>({})

  const {mutate: destroy, isPending: isPendingDelete} = useMutation(destroyCustomKeyMutationOptions(org))
  const {mutate: update, isPending: isPendingUpdate} = useMutation(
    updateCustomKeyMutationOptions({org, customKeyId: customKey.id}),
  )
  const confirm = useConfirm()

  const disableInputs = isPendingDelete || isPendingUpdate

  const onSetAdditionalData = useCallback((data: ProviderAdditionalData) => {
    additionalData.current = data
  }, [])

  const onCancelConfiguringModel = useCallback(() => {
    setConfiguringModel(null)
  }, [])

  const onSaveModelConfiguration = useCallback((modelKey: string, modelFormData: FormData) => {
    const configData: Record<string, unknown> = {}
    for (const [key, value] of modelFormData.entries()) {
      configData[key] = value
    }

    // For checkboxes, if they're not in FormData it means they're unchecked
    // We need to explicitly set them to false so they're persisted correctly
    const checkboxFields = ['toolCalling', 'vision', 'thinking']
    for (const field of checkboxFields) {
      if (!(field in configData)) {
        configData[field] = false
      }
    }

    setModelConfigurations(prev => ({...prev, [modelKey]: configData}))
    setConfiguringModel(null)
  }, [])

  function onError(error: Error) {
    setValidation(getGeneralValidationKind(error))
  }

  async function handleOnDelete() {
    const confirmed = await confirm({
      confirmButtonContent: 'Delete',
      confirmButtonType: 'danger',
      title: 'Delete API key',
      content: (
        <>
          Are you sure you want to delete the custom key &quot;<strong>{customKey.name}</strong>&quot;? This action
          cannot be undone.
        </>
      ),
    })

    if (confirmed) {
      destroy(
        {id: customKey.id},
        {
          onSuccess() {
            onClose()
            onDelete?.()
          },
          onError,
        },
      )
    }
  }

  async function onSubmitHandler(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()

    // Get form data from the form for provider-specific fields
    const htmlFormData = new FormData(event.currentTarget)
    const providerFormData = Object.fromEntries(htmlFormData.entries()) as Record<string, unknown>

    const basePayload = {
      ...formData,
      ...providerFormData,
      ...additionalData.current,
    }

    const {success, data, error} = formSchema.safeParse(basePayload)
    if (!success) {
      setValidation(validationKindFromZodError(error))
      return
    }

    setValidation(undefined)

    // @ts-expect-error — provider is not part of the payload, but is required for validation
    delete data.provider

    // Create a record that will be cast to UpdateCustomKeyUpdatePayload
    const updatePayload: Record<string, unknown> = {}

    if (data.name) {
      updatePayload.name = data.name
    }

    if ('deployment_url' in data && data.deployment_url) {
      updatePayload.deployment_url = data.deployment_url
    }

    if ('models' in data && data.models) {
      // Merge model configurations into the models payload
      const modelsWithConfig = applyModelConfigurations(
        data.models as Array<{id?: number; slug: string; name?: string}>,
        _modelConfigurations,
      )
      updatePayload.models = modelsWithConfig
    }

    // Handle API key encryption - only if user has provided a new key
    // (not the randomKey placeholder or empty)
    if (typeof data.api_key === 'string' && data.api_key.trim().length > 0 && data.api_key !== randomKey) {
      const encryptedKey = await encrypt(publicKey, data.api_key)
      const encodedKey = encode(encryptedKey)
      updatePayload.api_key = encodedKey
    }

    // Cast to UpdateCustomKeyUpdatePayload to ensure type safety at the API boundary
    update(updatePayload as UpdateCustomKeyUpdatePayload, {
      onSuccess: onUpdate,
      onError,
    })
  }

  const ProviderFields = useMemo(() => {
    return providerFields[customKey.provider]
  }, [customKey.provider]) as ComponentType<ProviderFieldProps<Provider>>

  // Prepare sub-form data
  const modelKey = configuringModel ? keyForModel(configuringModel) : ''
  const configFormId = useId()
  const savedConfig = configuringModel ? _modelConfigurations[modelKey] : undefined

  // Look up the full CustomModel from customModels to get persisted capability data
  const persistedModel = findPersistedModel(customModels, configuringModel)

  // Build the config model for the sub-form
  const configModel = buildConfigModel(configuringModel, savedConfig, persistedModel, customKey.id)

  // Handle close button - when in subform mode, go back instead of closing
  const handleClose = useCallback(() => {
    if (configuringModel) {
      onCancelConfiguringModel()
    } else {
      onClose()
    }
  }, [configuringModel, onCancelConfiguringModel, onClose])

  const providers = useProviders()

  return (
    <Dialog
      title={configuringModel ? 'Configure Model' : 'Edit API key'}
      onClose={handleClose}
      position="right"
      width="large"
      className={styles.AddEditDialogLayout}
      returnFocusRef={anchorRef}
      footerButtons={
        configuringModel
          ? [
              {content: 'Cancel', buttonType: 'default', onClick: onCancelConfiguringModel},
              {
                content: 'Add',
                buttonType: 'primary',
                onClick: () => {
                  // Trigger form submission by getting the form element via ref
                  if (configFormRef.current) {
                    const configFormData = new FormData(configFormRef.current)
                    onSaveModelConfiguration(modelKey, configFormData)
                  }
                },
                disabled: disableInputs,
              },
            ]
          : [
              {
                content: 'Delete',
                buttonType: 'danger',
                leadingVisual: TrashIcon,
                loading: isPendingDelete,
                disabled: isPendingUpdate,
                onClick() {
                  void handleOnDelete()
                },
                loadingAnnouncement: 'Deleting API key',
              },
              {content: 'Cancel', buttonType: 'default', onClick: onClose},
              {
                content: 'Save',
                buttonType: 'primary',
                type: 'submit',
                form: `${id}-form`,
                loading: isPendingUpdate,
                disabled: isPendingDelete,
                loadingAnnouncement: 'Editing API key',
              },
            ]
      }
    >
      {/* Main form - hidden when configuring a model */}
      <Stack
        as="form"
        id={`${id}-form`}
        className="height-full"
        style={{display: configuringModel ? 'none' : undefined}}
        onSubmit={onSubmitHandler as unknown as React.FormEventHandler<HTMLDivElement>}
      >
        {validation?.__general && (
          <Banner role="banner" title="Error" variant="critical" hideTitle description={validation.__general.error} />
        )}

        <FormControl id={`${id}-provider`} disabled>
          <ProviderPicker id={`${id}-provider`} providers={providers} selected={provider} disabled />
          <FormControl.Label>Provider</FormControl.Label>
        </FormControl>

        <FormControl required disabled={disableInputs}>
          <FormControl.Label>Name</FormControl.Label>
          <TextInput
            name="name"
            value={formData.name}
            onChange={e => {
              const newName = e.currentTarget.value
              setFormData(prev => ({...prev, name: newName}))
            }}
            data-1p-ignore
            placeholder={getSampleCustomKeyNameFor(provider)}
            className="width-full"
            autoComplete="off"
            aria-describedby={`${nameValidationId} ${nameCaptionId}`}
          />
          <FormValidationNode item={validation?.name} id={nameValidationId} />
          <FormControl.Caption id={nameCaptionId}>Models provided will be available under this key</FormControl.Caption>
        </FormControl>

        <APIKeyField
          disabled={disableInputs}
          onUpdatedAPIKey={setApiKey}
          provider={provider}
          validation={validation?.api_key}
          value={formData.api_key}
          onChange={value => setFormData(prev => ({...prev, api_key: value}))}
        />

        <ProviderFields
          customKey={customKey}
          apiKey={apiKey}
          validation={validation}
          isPending={disableInputs}
          setValidation={setValidation}
          onSetAdditionalData={onSetAdditionalData}
          org={org}
          onUpdateModel={onUpdate}
        />
      </Stack>

      {/* Sub-form for model configuration - hidden when not configuring */}
      {configModel && (
        <div style={{display: configuringModel ? undefined : 'none'}} className="height-full">
          <ModelConfigurationSubForm
            ref={configFormRef}
            model={configModel}
            customKeyName={customKey.name}
            disabled={disableInputs}
            formId={configFormId}
          />
        </div>
      )}
    </Dialog>
  )
}

function APIKeyField({
  provider,
  disabled,
  validation,
  onUpdatedAPIKey,
  value,
  onChange,
}: {
  provider: Provider
  disabled: boolean
  validation?: ValidationKind
  onUpdatedAPIKey: (apiKey: string) => void
  value: string
  onChange: (value: string) => void
}) {
  const apiKeyValue = value
  const canFetchNewModels =
    canFetchNewModelsFromProvider(provider) && value != null && value.trim().length > 0 && value !== randomKey
  const id = useId()
  const validationId = `api_key-validation-${id}`

  return (
    <FormControl required disabled={disabled}>
      <FormControl.Label>API key</FormControl.Label>
      <TextInput
        name="api_key"
        value={apiKeyValue}
        onChange={e => onChange(e.currentTarget.value)}
        data-1p-ignore
        type="password"
        autoComplete="new-password"
        className="width-full"
        aria-describedby={validationId}
        trailingAction={
          canFetchNewModels ? (
            <TextInput.Action onClick={() => onUpdatedAPIKey(value)} icon={SyncIcon} aria-label="Fetch new models" />
          ) : undefined
        }
      />
      <FormValidationNode item={validation} id={validationId} />
    </FormControl>
  )
}

try{ EditKeyDialog.displayName ||= 'EditKeyDialog' } catch {}
try{ ProviderFields.displayName ||= 'ProviderFields' } catch {}
try{ APIKeyField.displayName ||= 'APIKeyField' } catch {}