import type {CustomModel, SelectorCustomModel} from '../types'

/**
 * Helper function to generate a consistent key for model lookups.
 * Uses model id if available, otherwise falls back to slug.
 */
export function keyForModel(model: {id?: number; slug: string}): string {
  return model.id?.toString() ?? model.slug
}

/**
 * Helper function to set a numeric property on an object if the value is valid.
 * Only sets the property if the value can be converted to a positive number.
 */
export function setPropIfNumeric(obj: Record<string, unknown>, prop: string, config: Record<string, unknown>) {
  if (config[prop]) {
    const numVal = Number(config[prop])
    if (!isNaN(numVal) && numVal > 0) {
      obj[prop] = numVal
    }
  }
  return obj
}

/**
 * Helper function to normalize checkbox values from FormData to boolean.
 * Handles different formats: 'on', '1', true, or boolean true.
 */
export function normalizeCheckboxValue(value: unknown): boolean {
  return value === 'on' || value === '1' || value === true
}

/**
 * Helper function to build a config model for the model configuration sub-form.
 * Combines data from configuringModel, saved config, and optionally persisted model data.
 *
 * @param configuringModel - The model being configured
 * @param savedConfig - In-memory saved configuration (takes precedence)
 * @param persistedModel - Optional persisted model data from the database (for EditKeyDialog)
 * @param customKeyId - The custom key ID (0 for new keys)
 */
export function buildConfigModel(
  configuringModel: SelectorCustomModel | null,
  savedConfig: Record<string, unknown> | undefined,
  persistedModel?: CustomModel,
  customKeyId: number = 0,
): CustomModel | undefined {
  if (!configuringModel) {
    return undefined
  }

  return {
    id: configuringModel.id ?? 0,
    slug: configuringModel.slug,
    name: (savedConfig?.name as string | undefined) ?? persistedModel?.name ?? configuringModel.name,
    customKeyId,
    enabled: true,
    // Start with persisted capability data from the database (if model exists)
    // Otherwise default to false for new models
    toolCalling: persistedModel?.toolCalling ?? false,
    vision: persistedModel?.vision ?? false,
    thinking: persistedModel?.thinking ?? false,
    maxInputTokens: persistedModel?.maxInputTokens,
    maxOutputTokens: persistedModel?.maxOutputTokens,
    // Override with saved configuration if it exists (unsaved changes take precedence)
    ...(savedConfig && {
      toolCalling: normalizeCheckboxValue(savedConfig.toolCalling),
      vision: normalizeCheckboxValue(savedConfig.vision),
      thinking: normalizeCheckboxValue(savedConfig.thinking),
      maxInputTokens: savedConfig.maxInputTokens ? Number(savedConfig.maxInputTokens) : undefined,
      maxOutputTokens: savedConfig.maxOutputTokens ? Number(savedConfig.maxOutputTokens) : undefined,
    }),
  }
}

/**
 * Helper function to apply saved model configurations to an array of models.
 * Maps over models and merges their saved configuration data.
 *
 * @param models - Array of models to configure
 * @param modelConfigurations - Record of saved configurations keyed by model id/slug
 * @param options - Configuration options
 */
export function applyModelConfigurations(
  models: Array<{id?: number; slug: string; name?: string}>,
  modelConfigurations: Record<string, Record<string, unknown>>,
  options: {filterUIProperties?: boolean} = {},
): Array<Record<string, unknown>> {
  return models.map(model => {
    const config = modelConfigurations[keyForModel(model)]
    return configureModel(model, config, options)
  })
}

/**
 * Helper function to merge model configuration data with a model object.
 * Applies saved configuration settings for capabilities and token limits.
 *
 * @param model - The base model object
 * @param config - The configuration data to apply
 * @param options - Configuration options
 * @param options.filterUIProperties - If true, filters out UI-only fields like 'selected'
 */
export function configureModel(
  model: {id?: number; slug: string; name?: string},
  config: Record<string, unknown> | undefined,
  options: {filterUIProperties?: boolean} = {},
): Record<string, unknown> {
  let result: Record<string, unknown>

  if (options.filterUIProperties) {
    // Filter out UI-only properties (used by AddKeyDialog)
    const {id, slug, name} = model as Record<string, unknown>
    result = {slug}
    if (id !== undefined) {
      result.id = id
    }
    if (name) {
      result.name = name
    }
  } else {
    // Spread all model properties (used by EditKeyDialog)
    result = {...model}
  }

  if (!config) {
    return result
  }

  // Apply the configuration data to this model
  result = {
    ...result,
    // Convert checkbox values to boolean
    toolCalling: normalizeCheckboxValue(config.toolCalling),
    vision: normalizeCheckboxValue(config.vision),
    thinking: normalizeCheckboxValue(config.thinking),
  }

  // Only include numeric fields if they have valid values
  result = setPropIfNumeric(result, 'maxInputTokens', config)
  result = setPropIfNumeric(result, 'maxOutputTokens', config)

  // Include name if present in config (may override the model name)
  if (config.name) {
    result.name = config.name
  }

  return result
}

/**
 * Helper function to find a persisted model from the customModels array.
 * Looks up by id if available, otherwise by slug and customKeyId.
 *
 * @param customModels - Array of persisted custom models
 * @param configuringModel - The model being configured
 */
export function findPersistedModel(
  customModels: CustomModel[],
  configuringModel: (SelectorCustomModel & {customKeyId: number}) | null,
): CustomModel | undefined {
  if (!configuringModel) {
    return undefined
  }

  // If model has an id, find by id
  if (configuringModel.id !== undefined) {
    return customModels.find(m => m.id === configuringModel.id)
  }

  // Otherwise find by slug and customKeyId
  return customModels.find(m => m.slug === configuringModel.slug && m.customKeyId === configuringModel.customKeyId)
}
