import {useMutation} from '@github-ui/react-query'
import {Button, Stack} from '@primer/react'
import {Dialog, type DialogProps} from '@primer/react/experimental'
import {type FormEvent, startTransition, useCallback, useId, useRef, useState} from 'react'

import {getErrorMessageFromResponse} from '../helpers/extract-errors'
import {getGeneralValidationKind, type ValidationKind, validationKindFromZodError} from '../helpers/validation'
import {updateCustomModelMutationOptions, updateCustomModelSchema} from '../queries/update-custom-model'
import type {CustomModel} from '../types'
import {ModelConfigurationFields} from './ModelConfigurationFields'

interface ModelConfigurationDialogProps {
  customKeyName: string
  model: CustomModel
  org: string
  onUpdateModel: () => void
}

export function ModelConfigurationDialog({customKeyName, model, onUpdateModel, org}: ModelConfigurationDialogProps) {
  const [open, setOpen] = useState(false)
  const baseId = useId()
  const formId = `model-config-form-${baseId}`
  const dialogToggleButtonRef = useRef<HTMLButtonElement>(null)
  const onClose = useCallback(() => setOpen(false), [])
  const [validation, setValidation] = useState<Record<string, ValidationKind>>()
  const {mutate, isPending} = useMutation(updateCustomModelMutationOptions(org))
  const onSuccessfulUpdate = useCallback(() => {
    onUpdateModel()
    onClose()
  }, [onClose, onUpdateModel])
  const onSubmit = useCallback(
    (event: FormEvent<HTMLFormElement>) => {
      event.preventDefault()
      if (isPending) return

      const formData = new FormData(event.currentTarget)
      const payload = Object.assign(
        {id: model.id, enabled: model.enabled},
        Object.fromEntries(formData.entries()),
      ) as Record<string, unknown>

      const {success, data: validatedUpdate, error: zodError} = updateCustomModelSchema.safeParse(payload)
      if (!success) {
        setValidation(validationKindFromZodError(zodError))
        return
      }

      startTransition(() => {
        setValidation(undefined)
        mutate(validatedUpdate, {
          onSuccess: onSuccessfulUpdate,
          async onError(mutationError) {
            const message = await getErrorMessageFromResponse(mutationError)
            setValidation(getGeneralValidationKind(message, mutationError.message))
          },
        })
      })
    },
    [isPending, model, mutate, onSuccessfulUpdate],
  )

  return (
    <>
      <Button
        aria-label={`Configure ${model.name ?? model.slug} from ${customKeyName}`}
        variant="invisible"
        ref={dialogToggleButtonRef}
        onClick={() => setOpen(!open)}
      >
        Configure
      </Button>
      {open && (
        <Dialog
          onClose={onClose}
          title={`Edit configuration for ${model.slug} (${customKeyName})`}
          returnFocusRef={dialogToggleButtonRef}
          renderBody={DialogBodyWithoutPadding}
          footerButtons={[
            {
              buttonType: 'default',
              content: 'Cancel',
              onClick: onClose,
              disabled: isPending,
            },
            {
              buttonType: 'primary',
              content: 'Save',
              disabled: isPending,
              loading: isPending,
              type: 'submit',
              form: formId,
              loadingAnnouncement: 'Saving model configuration',
            },
          ]}
        >
          <Stack as="form" id={formId} className="height-full" onSubmit={onSubmit}>
            <ModelConfigurationFields
              className="pt-3 px-3"
              disabled={isPending}
              model={model}
              validation={validation}
            />
          </Stack>
        </Dialog>
      )}
    </>
  )
}

function DialogBodyWithoutPadding({children}: React.PropsWithChildren<DialogProps>) {
  return <Dialog.Body className="p-0">{children}</Dialog.Body>
}

try{ ModelConfigurationDialog.displayName ||= 'ModelConfigurationDialog' } catch {}
try{ DialogBodyWithoutPadding.displayName ||= 'DialogBodyWithoutPadding' } catch {}