import {ProvidersProvider} from '@github-ui/copilot-byok/providers/react'
import {PageBannerOutlet} from '@github-ui/page-banner'
import {copilotOrgSettingsModels} from '@github-ui/paths'
import {useChildRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {Outlet, type PathParam, useParams} from '@github-ui/react-router'
import {Label, Stack, UnderlineNav} from '@primer/react'
import {memo} from 'react'
import invariant from 'tiny-invariant'

import {PageHeading} from '../components/PageHeading'
import {CurrentOrgProvider} from '../contexts/CurrentOrgContext'
import type {copilotByokSettingsLayoutRoute} from './copilot-byok-settings-layout-route'
import {customModelsIndexRoute} from './CustomModelsIndex/custom-models-index-route'

type LayoutRouteParams = PathParam<(typeof copilotByokSettingsLayoutRoute)['path']>

export const CopilotByokSettingsLayout = memo(function CopilotByokSettingsLayout() {
  const org = useParams<LayoutRouteParams>().org
  invariant(org, 'org param is required')

  // TODO: Get this data from possible a layout route sub-query
  const {data} = useChildRouteQuery(customModelsIndexRoute, 'mainQuery')
  const providers = data?.availableProviders
  invariant(providers, 'providers are required')

  return (
    <CurrentOrgProvider value={org}>
      <ProvidersProvider providers={providers}>
        <PageBannerOutlet />

        <PageHeading name="Copilot models" />

        <Stack>
          <UnderlineNav aria-label="Default/Custom model menu" variant="flush">
            <UnderlineNav.Item href={copilotOrgSettingsModels({org})}>Default models</UnderlineNav.Item>
            <UnderlineNav.Item href={customModelsIndexRoute.generatePath({org})} aria-current>
              <span>
                Custom models
                <Label variant="success" className="ml-2">
                  Preview
                </Label>
              </span>
            </UnderlineNav.Item>
          </UnderlineNav>

          <Outlet />
        </Stack>
      </ProvidersProvider>
    </CurrentOrgProvider>
  )
})

try{ CopilotByokSettingsLayout.displayName ||= 'CopilotByokSettingsLayout' } catch {}